package com.example.productinventory.exception;
import org.springframework.http.*; import org.springframework.http.converter.HttpMessageNotReadableException; import org.springframework.web.bind.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(ResourceNotFoundException.class) public ApiError nf(ResourceNotFoundException e){return err(HttpStatus.NOT_FOUND,"PRODUCT_NOT_FOUND",e.getMessage(),Map.of());} @ExceptionHandler(MethodArgumentNotValidException.class) public ApiError val(MethodArgumentNotValidException e){Map<String,String> m=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->m.put(x.getField(),x.getDefaultMessage()));return err(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR","Request validation failed",m);} @ExceptionHandler(HttpMessageNotReadableException.class) public ApiError bad(HttpMessageNotReadableException e){return err(HttpStatus.BAD_REQUEST,"MALFORMED_REQUEST","Request body is malformed or contains invalid values",Map.of());} @ExceptionHandler(MethodArgumentTypeMismatchException.class) public ApiError type(MethodArgumentTypeMismatchException e){return err(HttpStatus.BAD_REQUEST,"INVALID_PARAMETER","Parameter '"+e.getName()+"' has an invalid value",Map.of());} @ExceptionHandler(Exception.class) public ApiError other(Exception e){return err(HttpStatus.INTERNAL_SERVER_ERROR,"INTERNAL_SERVER_ERROR","An unexpected error occurred",Map.of());} private ApiError err(HttpStatus s,String c,String m,Map<String,String> e){return new ApiError(Instant.now(),s.value(),c,m,e);} }